// สร้างลิงก์ขอสิทธิ์ Etsy (OAuth2 + PKCE) — เปิดลิงก์ที่ได้ในเบราว์เซอร์แล้วกดอนุญาต
function sha256Bytes(msgBytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = msgBytes.length;
  const withPad = new Uint8Array(((l + 72) >> 6) << 6); // ปัดขึ้นเป็นทวีคูณของ 64 ที่ >= l+9
  withPad.set(msgBytes);
  withPad[l] = 0x80;
  const bitLen = l * 8;
  const dv = new DataView(withPad.buffer);
  dv.setUint32(withPad.length - 4, bitLen >>> 0, false);
  dv.setUint32(withPad.length - 8, Math.floor(bitLen / 4294967296), false);
  const w = new Uint32Array(64);
  const rr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < withPad.length; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4, false);
    for (let j = 16; j < 64; j++) {
      const s0 = rr(w[j-15],7) ^ rr(w[j-15],18) ^ (w[j-15] >>> 3);
      const s1 = rr(w[j-2],17) ^ rr(w[j-2],19) ^ (w[j-2] >>> 10);
      w[j] = (w[j-16] + s0 + w[j-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,hh] = h;
    for (let j = 0; j < 64; j++) {
      const S1 = rr(e,6) ^ rr(e,11) ^ rr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[j] + w[j]) >>> 0;
      const S0 = rr(a,2) ^ rr(a,13) ^ rr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h = [(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  const outBytes = new Uint8Array(32);
  const odv = new DataView(outBytes.buffer);
  h.forEach((v, i) => odv.setUint32(i * 4, v, false));
  return outBytes;
}
function b64url(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return Buffer.from(s, 'latin1').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const cfg = $input.first().json;
const keystring = String(cfg.etsy_keystring || '').trim();
const redirectUri = String(cfg.redirect_uri || '').trim();
if (!keystring || /^YOUR_/i.test(keystring)) throw new Error('ยังไม่ได้กรอก etsy_keystring ในโหนด Etsy Auth Config');
if (!redirectUri || /^YOUR_/i.test(redirectUri)) throw new Error('ยังไม่ได้กรอก redirect_uri (คือ Production URL ของโหนด Webhook ในไฟล์นี้)');

// code_verifier: สุ่ม 43 ตัวอักษรตามสเปก PKCE
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
let rnd;
try { rnd = new Uint8Array(43); crypto.getRandomValues(rnd); }
catch (e) { rnd = new Uint8Array(43); for (let i = 0; i < 43; i++) rnd[i] = Math.floor(Math.random() * 256); }
let verifier = '';
for (let i = 0; i < 43; i++) verifier += chars[rnd[i] % chars.length];

const bytes = new Uint8Array(verifier.length);
for (let i = 0; i < verifier.length; i++) bytes[i] = verifier.charCodeAt(i);
const challenge = b64url(sha256Bytes(bytes));
const state = 'cbf' + Date.now().toString(36);

// เก็บ verifier ไว้ให้โหนดฝั่ง Webhook ใช้แลก token
const store = $getWorkflowStaticData('global');
store.etsy_code_verifier = verifier;
store.etsy_state = state;
store.etsy_keystring = keystring;
store.etsy_redirect_uri = redirectUri;

const scopes = 'listings_r listings_w shops_r';
const authUrl = 'https://www.etsy.com/oauth/connect' +
  '?response_type=code' +
  '&client_id=' + encodeURIComponent(keystring) +
  '&redirect_uri=' + encodeURIComponent(redirectUri) +
  '&scope=' + encodeURIComponent(scopes) +
  '&state=' + encodeURIComponent(state) +
  '&code_challenge=' + encodeURIComponent(challenge) +
  '&code_challenge_method=S256';

return [{ json: {
  ขั้นตอนต่อไป: 'คัดลอก auth_url ด้านล่างไปเปิดในเบราว์เซอร์ แล้วกด Allow Access — เสร็จแล้วหน้าเว็บจะแสดง refresh_token ให้เอง',
  auth_url: authUrl,
  scopes: scopes,
  redirect_uri_ที่ต้องตั้งในแอป_Etsy: redirectUri,
} }];

// แลก code ที่ Etsy ส่งกลับมาเป็น refresh token + ดึง shop_id และหมวดหมู่ที่เกี่ยวกับ coloring book ให้ด้วย
const store = $getWorkflowStaticData('global');
const q = ($input.first().json.query) || {};
const code = q.code;
const keystring = store.etsy_keystring;
const redirectUri = store.etsy_redirect_uri;
const verifier = store.etsy_code_verifier;

if (q.error) throw new Error('Etsy ปฏิเสธการขอสิทธิ์: ' + q.error + ' ' + (q.error_description || ''));
if (!code) throw new Error('ไม่พบพารามิเตอร์ code จาก Etsy');
if (!verifier) throw new Error('ไม่พบ code_verifier — ให้กลับไปกด Execute โหนด "1. สร้างลิงก์ขอสิทธิ์" ใหม่ก่อน แล้วค่อยเปิดลิงก์');
if (q.state && store.etsy_state && q.state !== store.etsy_state) throw new Error('state ไม่ตรง อาจเป็นลิงก์เก่า ให้เริ่มใหม่');

const form = 'grant_type=authorization_code' +
  '&client_id=' + encodeURIComponent(keystring) +
  '&redirect_uri=' + encodeURIComponent(redirectUri) +
  '&code=' + encodeURIComponent(code) +
  '&code_verifier=' + encodeURIComponent(verifier);

const parse = r => { if (r && typeof r === 'object') return r; try { return JSON.parse(String(r)); } catch (e) { return {}; } };
let tok = {}, lastErr = '';
for (const url of ['https://openapi.etsy.com/v3/public/oauth/token', 'https://api.etsy.com/v3/public/oauth/token']) {
  try {
    tok = parse(await this.helpers.httpRequest({
      method: 'POST', url,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: form, json: false, timeout: 30000,
    }));
    if (tok.access_token) break;
  } catch (e) { lastErr = String((e && e.message) || e); }
}
if (!tok.access_token) throw new Error('แลก token ไม่สำเร็จ: ' + lastErr);

store.etsy_refresh_token = tok.refresh_token;
const auth = { 'x-api-key': keystring, 'Authorization': 'Bearer ' + tok.access_token };

// shop_id
let shopId = '(หาไม่เจอ — ดูได้ที่ URL หน้าร้านของคุณ หรือใน Shop Manager)';
try {
  const me = parse(await this.helpers.httpRequest({ url: 'https://openapi.etsy.com/v3/application/users/me', headers: auth, json: true, timeout: 30000 }));
  if (me.shop_id) shopId = String(me.shop_id);
} catch (e) {}

// หมวดหมู่ (taxonomy) ที่มีคำว่า coloring — เอาไปใส่ etsy_taxonomy_id
let taxonomy = [];
try {
  const tx = parse(await this.helpers.httpRequest({ url: 'https://openapi.etsy.com/v3/application/seller-taxonomy/nodes', headers: { 'x-api-key': keystring }, json: true, timeout: 60000 }));
  const walk = (nodes, trail) => {
    for (const n of nodes || []) {
      const p = trail.concat(n.name);
      if (/colou?ring|digital print|coloring book/i.test(n.name)) taxonomy.push({ taxonomy_id: n.id, path: p.join(' > ') });
      if (n.children) walk(n.children, p);
    }
  };
  walk(tx.results, []);
  taxonomy = taxonomy.slice(0, 10);
} catch (e) {}

return [{ json: {
  '✅ สำเร็จ': 'คัดลอกค่าด้านล่างไปใส่ในโหนด Config ของ workflow หลัก (AI Coloring Book Factory)',
  etsy_refresh_token: tok.refresh_token,
  etsy_shop_id: shopId,
  หมวดหมู่ที่แนะนำ_เลือก1อันใส่_etsy_taxonomy_id: taxonomy,
  หมายเหตุ: 'refresh_token มีอายุ 90 วัน แต่ workflow หลักจะต่ออายุให้เองทุกครั้งที่รัน ถ้าไม่ได้รันเกิน 90 วันค่อยมาขอใหม่ที่ไฟล์นี้',
} }];
